import{_ as t,c as o,o as a,ag as n}from"./chunks/framework.DZ_cNctr.js";const r="/docs/screenshots/3d-grid.png",s="/docs/screenshots/3d-switch.png",i="/docs/screenshots/3d-position.png",d="/docs/screenshots/3d-layout-buttons.png",h="/docs/screenshots/3d-layout-main.png",l="/docs/screenshots/3d-mip.png",c="/docs/screenshots/3d-composite.png",p="/docs/screenshots/3d-opacity-ramp.png",m="/docs/screenshots/3d-gallery.png",x=JSON.parse('{"title":"3D Rendering","description":"View a z-stack as a 3D volume in your browser. WebGPU volume rendering with MIP or Composite, plus orthogonal XY, XZ and YZ planes with a shared crosshair. Free, desktop, no upload.","frontmatter":{"title":"3D Rendering","description":"View a z-stack as a 3D volume in your browser. WebGPU volume rendering with MIP or Composite, plus orthogonal XY, XZ and YZ planes with a shared crosshair. Free, desktop, no upload."},"headers":[],"relativePath":"guides/3d-rendering.md","filePath":"guides/3d-rendering.md"}'),g={name:"guides/3d-rendering.md"};function u(f,e,w,b,y,v){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_3d-rendering" tabindex="-1">3D Rendering <a class="header-anchor" href="#_3d-rendering" aria-label="Permalink to &quot;3D Rendering&quot;">​</a></h1><p>A z-stack is a volume. Planar view shows it one plane at a time, or flattened by a <a href="./z-projection.html">projection</a>. 3D shows the whole thing at once: three orthogonal planes with a shared crosshair, next to a volume rendering you can turn with the mouse.</p><p>3D is part of the same viewer. There is nothing to install and nothing to upload. It opens from the image you already have open, and it takes your channels, your place and your annotations with it.</p><p><img src="'+r+'" alt="The viewer in 3D on the zebrafish lateral line primordium: XY, XZ and YZ planes with a shared crosshair, and the 3D volume rendering in Composite, membranes green and nuclei red" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><div class="warning custom-block"><p class="custom-block-title">What you need</p><p>3D needs a desktop browser with <strong>WebGPU</strong>, and an image that has more than one z-section. It opens images from a URL. See <a href="#requirements-and-limits">Requirements and limits</a> for the full list. Everything else in the viewer works without it.</p></div><h2 id="open-an-image-in-3d" tabindex="-1">Open an image in 3D <a class="header-anchor" href="#open-an-image-in-3d" aria-label="Permalink to &quot;Open an image in 3D&quot;">​</a></h2><p>Planar is the default. An image always opens in Planar, and 3D is one click away.</p><ul><li><strong>The 3D button.</strong> In the Navigation panel, next to the Z slider, the Planar | 3D switch has a <strong>3D</strong> button.</li><li><strong>The 3D badge.</strong> The header shows the mode. Click the badge to switch.</li><li><strong>The offer at open.</strong> When an image has z-sections, a notice over the image says &quot;This image has 42 z-sections&quot; and offers <strong>Open in 3D</strong>. It goes away on its own after about 12 seconds. The cross dismisses it for the rest of the session.</li><li><strong>A link.</strong> A link with <code>mode=3d</code> opens in 3D. See <a href="#link-parameters">Link parameters</a>.</li></ul><p><img src="'+s+'" alt="The Navigation tab with the Planar | 3D switch above the Z-slice slider, Planar selected" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>To go back, click <strong>Planar</strong> in the switch or the 3D badge.</p><p>If 3D cannot open an image, the 3D button shows disabled and its tooltip says why. If the browser has no WebGPU, or the image has one z-section or is RGB, or you are on a phone or tablet, the switch is not offered at all.</p><h3 id="what-comes-with-you" tabindex="-1">What comes with you <a class="header-anchor" href="#what-comes-with-you" aria-label="Permalink to &quot;What comes with you&quot;">​</a></h3><p>A switch keeps your place. These carry over, and carry back when you return to Planar:</p><ul><li>the <strong>channels</strong>: on or off, colour, contrast window and gamma</li><li>the <strong>z-plane</strong> and the <strong>time point</strong></li><li><strong>INV</strong> and the <strong>background</strong></li><li>your <a href="#annotations-across-the-switch">annotations</a></li></ul><h3 id="plates" tabindex="-1">Plates <a class="header-anchor" href="#plates" aria-label="Permalink to &quot;Plates&quot;">​</a></h3><p>A field of a plate opens in 3D when it has z-sections. The plate navigation (the well map, the arrows and the field list) stays in the Navigation panel. Pick a well or a field there, and that field opens in 3D at the same z and time point.</p><p>In 3D a plate has only Field view. <strong>Well</strong> and <strong>Plate</strong> are disabled, with &quot;Available in Planar&quot; as their tooltip. If you are in Well or Plate view when you switch, Planar first moves to the field you are looking at.</p><p>See <a href="./hcs-plates.html">HCS Plates</a> for the plate views.</p><h2 id="the-four-panels" tabindex="-1">The four panels <a class="header-anchor" href="#the-four-panels" aria-label="Permalink to &quot;The four panels&quot;">​</a></h2><p>3D draws four panels:</p><table tabindex="0"><thead><tr><th>Panel</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>XY</strong></td><td>The plane you know from Planar, at the crosshair&#39;s z</td></tr><tr><td><strong>XZ</strong></td><td>A side cut through the stack, at the crosshair&#39;s y</td></tr><tr><td><strong>YZ</strong></td><td>The other side cut, at the crosshair&#39;s x</td></tr><tr><td><strong>3D</strong></td><td>The volume rendering</td></tr></tbody></table><p>The three planes share one <strong>crosshair</strong>. In Crosshair mode, click or drag on a plane to move it. The other planes and the volume follow. The <strong>Position</strong> card holds the X, Y and Z sliders and, on a time-lapse image, T. Press <code>M</code> to fold or open it.</p><p><img src="'+i+'" alt="The Position card with X, Y and Z sliders, each showing the voxel index and the physical position" style="max-width:232px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="anatomical-orientation" tabindex="-1">Anatomical orientation <a class="header-anchor" href="#anatomical-orientation" aria-label="Permalink to &quot;Anatomical orientation&quot;">​</a></h3><p>Some images record which way is up in the body: superior and inferior, left and right, anterior and posterior. This comes from the OME-Zarr metadata (the anatomical orientation proposal, RFC-4). When an image has it, 3D uses it:</p><ul><li>The ends of each axis carry their anatomical names, at the edges of the planes, in the <strong>Position</strong> card and on the axis lock buttons of the 3D panel.</li><li><strong>Medical</strong> on the canvas toolbar shows the planes the radiological way: superior up, and the patient&#39;s right on the left of the screen.</li><li>The image&#39;s Info dialog lists the orientation.</li></ul><p>Without that metadata, the axes are named x, y and z, and <strong>Medical</strong> is disabled.</p><h3 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h3><p>The layout buttons on the canvas toolbar choose how the panels share the space:</p><ul><li><strong>2×2</strong> shows four equal panels. This is the default.</li><li><strong>1+3</strong> shows one big panel and three small ones.</li><li><strong>1</strong> shows one panel.</li></ul><p>The buttons labelled XY, XZ, YZ and 3D pick the big panel. In the 2×2 layout, pressing one of them switches to 1+3 with that panel large. Opened without a <code>main</code> parameter, the big panel is the 3D one.</p><p><img src="'+d+'" alt="The canvas toolbar: three layout buttons (2×2, 1+3, 1), the XY, XZ, YZ and 3D main-panel buttons, Crosshair and Pan, Sync zoom, Sync position, Medical and Reset" style="max-width:700px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p><img src="'+h+'" alt="The 1+3 layout: the 3D volume large on the left, the XY, XZ and YZ planes stacked on the right" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h3 id="moving-around" tabindex="-1">Moving around <a class="header-anchor" href="#moving-around" aria-label="Permalink to &quot;Moving around&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Where</th><th>Action</th></tr></thead><tbody><tr><td>A plane, Crosshair mode (default)</td><td>Click or drag to move the crosshair. The wheel moves the slice. <code>Cmd</code> or <code>Ctrl</code> + wheel zooms. <code>Shift</code> + drag pans</td></tr><tr><td>A plane, Pan mode</td><td>Drag pans. The wheel zooms. <code>Cmd</code> or <code>Ctrl</code> + click moves the crosshair</td></tr><tr><td>The 3D panel</td><td>Drag to orbit. <code>Shift</code> + drag, or right drag, pans. The wheel zooms. Double-click resets</td></tr></tbody></table><p>Other controls on the canvas toolbar:</p><ul><li><strong>Sync zoom</strong> makes the planes zoom together. <strong>Sync position</strong> makes them pan together, and on, they centre on the crosshair.</li><li><strong>Medical</strong> uses the medical plane convention, with the superior side up. It needs anatomical orientation in the image&#39;s metadata, and is disabled without it.</li><li><strong>Reset</strong> fits the planes and resets the 3D camera.</li></ul><p>On the 3D panel, <strong>Free</strong>, <strong>X</strong>, <strong>Y</strong> and <strong>Z</strong> lock the orbit to one axis. <strong>Front</strong>, <strong>Side</strong> and <strong>Top</strong> jump to a quick view. <strong>Outlines</strong> frames the three crosshair planes.</p><p>The full list of keys is in the viewer&#39;s Help dialog, under <code>?</code> or <code>F1</code>. A few are worth knowing now: <code>1</code> to <code>9</code> turn channels on and off, <code>+</code> and <code>-</code> zoom the plane under the mouse, <code>0</code> fits it, and <code>,</code> and <code>.</code> step through time.</p><h2 id="mip-and-composite" tabindex="-1">MIP and Composite <a class="header-anchor" href="#mip-and-composite" aria-label="Permalink to &quot;MIP and Composite&quot;">​</a></h2><p>The render mode sits on the 3D panel, next to the scene buttons.</p><p><strong>MIP</strong> (maximum intensity projection) shows the brightest value along each ray through the volume. It is the 3D version of the maximum projection in <a href="./z-projection.html">Z-Projection</a>. Use it for bright, sparse signal: nuclei, neurons, axons, puncta. It follows each channel&#39;s contrast window.</p><p><strong>Composite</strong> accumulates colour and opacity along each ray, front to back. Near structures hide far ones, so a surface looks like a surface. Use it for solid or layered objects, such as a skull or a carp in CT. Which values count as solid is set by the <a href="#the-opacity-ramp">opacity ramp</a>.</p><p>The same volume, both ways. These are the nuclei of a small cell cluster, 236 planes, two channels.</p><div style="display:flex;gap:1rem;flex-wrap:wrap;margin:1rem 0;"><figure style="flex:1 1 320px;margin:0;"><img src="'+l+'" alt="The nuclei volume in MIP: bright, flat and glowing, with every nucleus seen through the ones in front" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85em;color:var(--vp-c-text-2);margin-top:0.4rem;"><strong>MIP.</strong> Every nucleus shows, near or far, at its brightest. </figcaption></figure><figure style="flex:1 1 320px;margin:0;"><img src="'+c+'" alt="The same volume in Composite: nuclei as solid bodies with their rims in blue, near ones hiding far ones" style="width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;"><figcaption style="font-size:0.85em;color:var(--vp-c-text-2);margin-top:0.4rem;"><strong>Composite.</strong> Near nuclei hide far ones, so the cluster reads as a body in depth. </figcaption></figure></div><p>When the image opens, one channel starts in Composite and several channels start in MIP. Change it with one click. The link remembers the mode when it differs from that default (<code>rm=mip</code> or <code>rm=composite</code>).</p><p>The scene buttons next to it choose what the 3D panel draws:</p><ul><li><strong>Volume</strong>: the volume only</li><li><strong>Slices</strong>: the three crosshair planes only</li><li><strong>Both</strong>: the volume in front of the planes</li><li><strong>None</strong>: no image, only annotations, the crosshair and outlines</li></ul><p>In the <strong>Settings</strong> card of the Channels tab, <strong>Brightness</strong> has a slider, and in Composite so does <strong>Density</strong>. <strong>LIGHT</strong> turns on gradient shading and works in Composite only.</p><p>Dragging is kept fast on purpose. While the view moves, the volume is drawn coarser, with fewer pixels and fewer samples. A moment after you stop, it redraws at full quality.</p><h2 id="channels-in-3d" tabindex="-1">Channels in 3D <a class="header-anchor" href="#channels-in-3d" aria-label="Permalink to &quot;Channels in 3D&quot;">​</a></h2><p>In View Options, the Channels tab works as in Planar: toggle a channel, change its colour, set its contrast window. The shown channels blend into one volume.</p><p><strong>3D draws up to four channels at once.</strong> An image can have more. List them all, show any four. If you turn on a fifth, 3D refuses and says &quot;3D shows up to 4 channels at once. Hide one first.&quot; If Planar was showing more than four when you switched, 3D keeps the first four and shows the same notice.</p><h3 id="heavy-reads" tabindex="-1">Heavy reads <a class="header-anchor" href="#heavy-reads" aria-label="Permalink to &quot;Heavy reads&quot;">​</a></h3><p>3D reads the channels you show from the server. For a large volume with several channels, that is a lot of data. When 3D would read two or more channels and more than about 250 MB, a hint offers to keep one:</p><blockquote><p>3D will read 2 channels (about 380 MB). Show only EGFP?</p></blockquote><p>Click <strong>Yes</strong> and 3D hides the other channels, so it reads one. Click <strong>No</strong> and it reads them all. The hint shows once per image in a session and never blocks the view. When you go back to Planar, the channels 3D hid are hidden there too.</p><h3 id="inv-and-bw" tabindex="-1">INV and BW <a class="header-anchor" href="#inv-and-bw" aria-label="Permalink to &quot;INV and BW&quot;">​</a></h3><p><strong>INV</strong> in the Settings card flips dark and bright, as in Planar, and it carries over with the switch in both directions. <strong>BW</strong> in the same card shows the composite in greyscale.</p><h2 id="the-opacity-ramp" tabindex="-1">The opacity ramp <a class="header-anchor" href="#the-opacity-ramp" aria-label="Permalink to &quot;The opacity ramp&quot;">​</a></h2><p>In Composite, every channel card has a <strong>3D opacity ramp</strong>. It is separate from the contrast window of Planar. The window says how bright a value looks. The ramp says how opaque it is.</p><p>Values at or below the ramp&#39;s low end add no opacity. Values at or above its high end are fully opaque. In between, opacity rises in a straight line. Move the low end up to cut noise and haze. Move the high end down to make a structure more solid.</p><p>Two buttons sit on the section&#39;s header:</p><ul><li><strong>2D</strong> starts the ramp at the channel&#39;s 2D contrast window. This is the quickest way to a first result.</li><li><strong>FIT</strong> zooms the slider to the ramp&#39;s range. When the ramp is narrow compared with the full intensity range, a slider covering everything is too coarse to adjust. FIT makes it fine. Press it again to see the full range. It fits itself the first time a narrow ramp appears.</li></ul><p>In MIP the ramp section is not shown.</p><p><img src="'+p+'" alt="A channel card in Composite: the Contrast and Gamma sections, then the 3D opacity ramp section with its slider and the 2D and FIT buttons" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="annotations-across-the-switch" tabindex="-1">Annotations across the switch <a class="header-anchor" href="#annotations-across-the-switch" aria-label="Permalink to &quot;Annotations across the switch&quot;">​</a></h2><p>Annotations are one set for Planar and 3D. Switching keeps them.</p><ul><li>They are kept <strong>per image</strong>. On a plate, they are kept <strong>per field</strong>.</li><li>Both modes read and write the same saved set. A switch saves what the mode you leave holds, and the other mode loads it.</li></ul><p>In 3D you can draw on any plane. The second bar holds the tools: Select (<code>V</code>), Polygon (<code>P</code>, drag for freehand), Wand (<code>W</code>), Brush (<code>R</code>) and Distance (<code>D</code>). Under <strong>More</strong> are Point (<code>B</code>), Line (<code>L</code>), Angle (<code>G</code>) and Text (<code>T</code>). <code>Cmd</code> or <code>Ctrl</code> + click still moves the crosshair. <code>Escape</code> cancels and <code>Cmd</code> + <code>Z</code> undoes.</p><p>A shape is full on its own slice and faint on the other slices of its plane. It also shows where it crosses the two other planes. Lines and outlines show in 3D too.</p><p><strong>Structure</strong> mode outlines one structure over several slices, and its volume shows in 3D. Switch between <strong>Annotation</strong> and <strong>Structure</strong> on the second bar.</p><p>See <a href="./annotations.html">Annotations</a> for the tools, templates and export.</p><h2 id="link-parameters" tabindex="-1">Link parameters <a class="header-anchor" href="#link-parameters" aria-label="Permalink to &quot;Link parameters&quot;">​</a></h2><p>A link with <code>mode=3d</code> opens in 3D. Without <code>mode</code>, it opens in Planar. The 3D view also reads these:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Meaning</th></tr></thead><tbody><tr><td><code>layout</code></td><td><code>grid</code> (default), <code>main</code> or <code>single</code></td></tr><tr><td><code>main</code></td><td>The big panel: <code>xy</code>, <code>xz</code>, <code>yz</code> or <code>v3d</code> (default <code>v3d</code>)</td></tr><tr><td><code>rm</code></td><td>Render mode: <code>mip</code> or <code>composite</code>. Left out, the image&#39;s default</td></tr><tr><td><code>cam</code></td><td>An opening camera: <code>cam=&lt;yaw&gt;,&lt;pitch&gt;[,&lt;zoom&gt;]</code>, angles in degrees</td></tr><tr><td><code>sync</code>, <code>syncpos</code></td><td><code>0</code> turns off Sync zoom or Sync position</td></tr><tr><td><code>orient</code></td><td><code>medical</code> for the medical plane convention</td></tr><tr><td><code>pm</code>, <code>pt</code></td><td>Pointer mode (<code>pan</code>) and the planes&#39; transforms</td></tr><tr><td><code>t</code></td><td>The time point</td></tr></tbody></table><p><code>cam</code> frames the first view. The viewer uses it once and takes it out of the address bar, and <strong>Link</strong> never writes it. A link you copy opens on the standard start view, not on your current camera.</p><p>A link that cannot open in 3D opens in Planar, with a notice that says why. That is the case on a phone or tablet, in a browser without WebGPU, and for an image with one z-section or RGB.</p><p>See <a href="./sharing.html">Sharing Views</a> for how links work in general. In 3D the header&#39;s <strong>Link</strong> button copies the 3D link, and <strong>Screenshot</strong> saves the 3D view.</p><h2 id="requirements-and-limits" tabindex="-1">Requirements and limits <a class="header-anchor" href="#requirements-and-limits" aria-label="Permalink to &quot;Requirements and limits&quot;">​</a></h2><ul><li><strong>A browser with WebGPU.</strong> Without it, 3D is not offered, and its code is never downloaded.</li><li><strong>Desktop only.</strong> On a phone or tablet, the viewer stays in Planar.</li><li><strong>A z-stack.</strong> The image needs more than one z-section and must not be RGB.</li><li><strong>A URL.</strong> 3D opens images from a web address. A local folder, an <code>.ozx</code> file and a token-protected store stay in Planar. The 3D button shows disabled, with the reason as its tooltip.</li><li><strong>Four channels at once.</strong> See <a href="#channels-in-3d">Channels in 3D</a>.</li><li><strong>A connection.</strong> 3D is loaded the first time you switch, and the <a href="./../install-and-offline.html">offline install</a> does not include it. Planar keeps working offline. If the 3D code cannot be loaded, for example right after a new release, the viewer asks you to reload and stays in Planar.</li><li><strong>Heavy reads.</strong> Large volumes take time and bandwidth. See <a href="#heavy-reads">Heavy reads</a>.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>The Example Gallery has a <strong>3D</strong> filter, and a <strong>3D</strong> badge on every tile that shows depth. Seven tiles open straight in 3D. Each link below is the link the tile opens.</p><table tabindex="0"><thead><tr><th>Example</th><th>Opens as</th><th>Link</th></tr></thead><tbody><tr><td>Lateral line primordium, zebrafish (IDR idr0079), 1584×788×142, 2 channels</td><td>Composite</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0079A%2Fidr0079_images.zarr&amp;c=0%3Aon%3A00FF00%3A5%3A200%3A1.00%2C1%3Aon%3AFF0000%3A10%3A160%3A1.00&amp;mode=3d&amp;rm=composite&amp;cam=25%2C-20%2C1.7" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Neurons in marmoset visual cortex, 1024×1024×314</td><td>MIP</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Fmarmoset_neurons.ome.zarr&amp;c=0%3Aon%3A00FF00%3A10%3A140%3A1.00&amp;mode=3d&amp;rm=mip&amp;cam=20%2C-25%2C1.4" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Axons in mouse barrel cortex, in vivo, 1464×1033×76</td><td>MIP</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Fneocortical_layer_1_axons.ome.zarr&amp;c=0%3Aon%3AFFFFFF%3A15%3A120%3A1.00&amp;mode=3d&amp;rm=mip&amp;cam=15%2C-30%2C1.4" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Head MRI, 256×256×109, medical convention</td><td>Composite</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Fmri_woman.ome.zarr&amp;mode=3d&amp;rm=composite&amp;cam=30%2C-15%2C1.5&amp;orient=medical" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Cerebral aneurysm, rotational angiography (C-arm x-ray), 256×256×256</td><td>Composite</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Faneurism.ome.zarr&amp;mode=3d&amp;rm=composite&amp;cam=30%2C-20%2C1.7" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Skull phantom, rotational CT, 256×256×256</td><td>Composite</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Fskull.ome.zarr&amp;c=0%3Aon%3AFFFFFF%3A30%3A200%3A1.00&amp;mode=3d&amp;rm=composite&amp;cam=-60%2C-10%2C1.4" target="_blank" rel="noreferrer">Open in 3D</a></td></tr><tr><td>Carp, CT, 256×256×512</td><td>Composite</td><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fome-zarr-scivis.s3.us-east-1.amazonaws.com%2Fv0.5%2F96x2%2Fcarp.ome.zarr&amp;c=0%3Aon%3AFFFFFF%3A1000%3A2200%3A1.00&amp;mode=3d&amp;rm=composite&amp;cam=90%2C-75%2C1.2" target="_blank" rel="noreferrer">Open in 3D</a></td></tr></tbody></table><p><img src="'+m+'" alt="The Example Gallery with the 3D filter on, showing tiles for the marmoset neurons, the head MRI, the mouse axons, the aneurysm, the skull and the carp" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>A good first try is the lateral line, which opens in Composite. Click <strong>MIP</strong> to compare. The marmoset neurons open in MIP, so try Composite there.</p><p>The other z-stacks under the <strong>3D</strong> filter, such as the confocal stacks and two plates from IDR, open in Planar with their curated views. Click <strong>3D</strong> to see them as volumes.</p><div class="tip custom-block"><p class="custom-block-title">Credits</p><p>The six volumes other than the zebrafish come from <a href="https://github.com/InsightSoftwareConsortium/OMEZarrOpenSciVisDatasets" target="_blank" rel="noreferrer">OME-Zarr Open SciVis Datasets</a>, by McCormick, M. (2025), <a href="https://doi.org/10.5281/zenodo.17495294" target="_blank" rel="noreferrer">doi:10.5281/zenodo.17495294</a>, recorded as CC BY 4.0. The zebrafish is IDR idr0079, CC BY 4.0. Each gallery tile shows its dataset&#39;s credit.</p></div><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./z-projection.html">Z-Projection</a>: flatten a stack into one image instead</li><li><a href="./channels.html">Channels</a>: colour, contrast and gamma, which carry into 3D</li><li><a href="./annotations.html">Annotations</a>: the tools you draw with in both modes</li><li><a href="./sharing.html">Sharing Views</a>: links, including <code>mode=3d</code></li><li><a href="./hcs-plates.html">HCS Plates</a>: open a plate field in 3D</li><li><a href="./supported-formats.html">Supported Formats</a>: what opens, and what 3D needs</li></ul>',90)])])}const D=t(g,[["render",u]]);export{x as __pageData,D as default};
